class Solution {
  public int furthestDistanceFromOrigin(String moves) {
    int balance = 0, wildcards = 0;
    for (int i = 0; i < moves.length(); i++) {
      char move = moves.charAt(i);
      if (move == 'L') balance--;
      else if (move == 'R') balance++;
      else wildcards++;
    }
    return Math.abs(balance) + wildcards;
  }
}
